local OlivePressMaker = {}
local PRODUCTS = {
    iron_olivepress = { name = "Železni oljčna preša", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni oljčna preša za kuhinjo." },
    bronze_olivepress = { name = "Bronast oljčna preša", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast oljčna preša za kuhinjo." },
    silver_olivepress = { name = "Srebrn oljčna preša", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn oljčna preša za kuhinjo." },
    gilded_olivepress = { name = "Pozlačen oljčna preša", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen oljčna preša za kuhinjo." },
    jewel_set_olivepress = { name = "Draguljast oljčna preša", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast oljčna preša za kuhinjo." },
    royal_sovereign_olivepress = { name = "Kraljevski suveren oljčna preša", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren oljčna preša z biseri za krono." },
}
local BUILDINGS = {
    olivepress_workshop = { name = "Olivepress delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    olivepress_house = { name = "Olivepress hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_olivepress_atelier = { name = "Mojstrski olivepress atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_olivepress_palace = { name = "Suverena olivepress palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
OlivePressMaker.ironStock = 18; OlivePressMaker.bronzeStock = 14; OlivePressMaker.woodStock = 12; OlivePressMaker.leatherStock = 8; OlivePressMaker.silverStock = 8; OlivePressMaker.goldStock = 6; OlivePressMaker.jewelStock = 4; OlivePressMaker.pearlStock = 4
OlivePressMaker.productStock = {}; OlivePressMaker.buildings = {}; OlivePressMaker.maker = nil; OlivePressMaker.activeMaking = {}; OlivePressMaker.totalProducts = 0; OlivePressMaker.dayTimer = 0
function OlivePressMaker.init() OlivePressMaker.ironStock=18; OlivePressMaker.bronzeStock=14; OlivePressMaker.woodStock=12; OlivePressMaker.leatherStock=8; OlivePressMaker.silverStock=8; OlivePressMaker.goldStock=6; OlivePressMaker.jewelStock=4; OlivePressMaker.pearlStock=4; OlivePressMaker.productStock={}; OlivePressMaker.buildings={}; OlivePressMaker.maker=nil; OlivePressMaker.activeMaking={}; OlivePressMaker.totalProducts=0; OlivePressMaker.dayTimer=0; print("[OlivePressMaker] Royal Olive Press Maker System initialized (6 products, 4 buildings)") end
function OlivePressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OlivePressMaker.maker={name=n or ("Prešar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prešar najet: %s (spretnost: %d)",OlivePressMaker.maker.name,s),"success") end; return true end
function OlivePressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OlivePressMaker.build(id) local ok,e=OlivePressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OlivePressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OlivePressMaker.getQualityBonus() local b=0; for _,bd in ipairs(OlivePressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OlivePressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and OlivePressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and OlivePressMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and OlivePressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and OlivePressMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and OlivePressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OlivePressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and OlivePressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and OlivePressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #OlivePressMaker.buildings==0 then return false,"Potrebna prešna delavnica" end; if not OlivePressMaker.maker then return false,"Potreben presar" end; return true end
function OlivePressMaker.make(pt,qty) qty=qty or 1; local ok,e=OlivePressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then OlivePressMaker.ironStock=OlivePressMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then OlivePressMaker.bronzeStock=OlivePressMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then OlivePressMaker.woodStock=OlivePressMaker.woodStock-d.woodCost*qty end; if d.leatherCost then OlivePressMaker.leatherStock=OlivePressMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then OlivePressMaker.silverStock=OlivePressMaker.silverStock-d.silverCost*qty end; if d.goldCost then OlivePressMaker.goldStock=OlivePressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then OlivePressMaker.jewelStock=OlivePressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then OlivePressMaker.pearlStock=OlivePressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if OlivePressMaker.maker then t=math.max(1,t-math.floor(OlivePressMaker.maker.skill/13)) end; table.insert(OlivePressMaker.activeMaking,{id="olivepress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OlivePressMaker.completeMaking(m) local q=1.0+(OlivePressMaker.getQualityBonus()/100); if OlivePressMaker.maker then q=q+(OlivePressMaker.maker.skill/140) end; q=math.min(2.5,q); OlivePressMaker.productStock[m.productType]=(OlivePressMaker.productStock[m.productType] or 0)+m.quantity; OlivePressMaker.totalProducts=OlivePressMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OlivePressMaker.maker then OlivePressMaker.maker.itemsMade=OlivePressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then OlivePressMaker.maker.skill=math.min(100,OlivePressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Preša izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"olivepress.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function OlivePressMaker.update(dt) if not _G.state then return end; OlivePressMaker.dayTimer=OlivePressMaker.dayTimer+dt; if OlivePressMaker.dayTimer>=30 then OlivePressMaker.dayTimer=0; for i=#OlivePressMaker.activeMaking,1,-1 do local m=OlivePressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OlivePressMaker.completeMaking(m); table.remove(OlivePressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OlivePressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OlivePressMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OlivePressMaker.getStats() return {ironStock=OlivePressMaker.ironStock,bronzeStock=OlivePressMaker.bronzeStock,woodStock=OlivePressMaker.woodStock,leatherStock=OlivePressMaker.leatherStock,silverStock=OlivePressMaker.silverStock,goldStock=OlivePressMaker.goldStock,jewelStock=OlivePressMaker.jewelStock,pearlStock=OlivePressMaker.pearlStock,productStock=OlivePressMaker.productStock,numBuildings=#OlivePressMaker.buildings,hasMaker=OlivePressMaker.maker~=nil,makerName=OlivePressMaker.maker and OlivePressMaker.maker.name or "—",makerSkill=OlivePressMaker.maker and OlivePressMaker.maker.skill or 0,activeMaking=#OlivePressMaker.activeMaking,totalProducts=OlivePressMaker.totalProducts} end
return OlivePressMaker
